def clean(value):
    return re.sub(r"\s+", " ", html.unescape(str(value or ""))).strip()


def build_species():
    details = {}
    for line in CONTEXT.strip().splitlines():
        key, interests, fears, behavior = line.split("|", 3)
        details[key] = (interests, fears, behavior)
    rows = []
    brief = (ROOT / "docs/mobtalk-0.2-plan.md").read_text(encoding="utf-8-sig")
    for line in brief.splitlines():
        if not re.match(r"^\| [a-z_]+ \|", line):
            continue
        _, key, description, names, _ = line.split("|", 4)
        key, description = key.strip(), description.strip()
        if key not in details:
            raise ValueError(f"No contextual profile for {key}")
        name, worldview = description.split(":", 1)
        name = {"ДраконКрая":"Дракон Края", "Древнийстраж":"Древний страж"}.get(name, name)
        worldview = worldview.strip().replace("/", ", ")
        for old, new in {"отмаленькой":"от маленькой", "ксвоим":"к своим", "допровокации":"до провокации", "срезкими":"с резкими", "своиламы":"свои ламы", "какдом":"как дом", "личныеграницы":"личные границы", "устройствомира":"устройство мира", "реальнаяагрессия":"реальная агрессия", "противсобеседника":"против собеседника", "вопросысподвохом":"вопросы с подвохом", "перетрактовкаочевидного":"переосмысление очевидного", "испор мотивовтрёхголов":"и спор мотивов трёх голов", "незрительныевыдумки":"не допускай зрительных выдумок", "НЕдобрый":"не добрый"}.items():
            worldview = worldview.replace(old, new)
        interests, fears, behavior = details[key]
        family = next((family for family, members in FAMILIES.items() if key in members), "gentle")
        labels = [clean(item) for item in names.strip().split(";")]
        if len(labels) != 3:
            raise ValueError(f"Expected three approved archetypes for {key}")
        variants = []
        for slot, label in enumerate(labels):
            motivation = MOTIVATIONS[key][slot] if key in MOTIVATIONS else archetype_motivation(label)
            target = MANUAL_VOICE_TARGETS[key][slot] if key in MANUAL_VOICE_TARGETS else VOICE_TARGETS[family][slot]
            # Gender/age are casting preferences, never a claim about the Minecraft entity's sex.
            gender = NATIVE_GENDER.get(key, "male")
            if slot == 1 and family in {"small", "lively", "strange"}:
                gender = "female" if gender == "male" else "male"
            age = ["young", "middle_aged", "old"][slot]
            variants.append({"name": label, "prompt": f"Твой индивидуальный архетип — {label.lower()}. {motivation} Эти приоритеты проявляй в темах «{interests.lower()}»; страхи вида не отменяются. {voice_style(target)}", "voiceId": "", "voiceRequirements": target, "preferredGender": gender, "preferredAge": age})
        rows.append({"id": f"minecraft:{key}", "name": name, "prompt": f"Ты {name.lower()}. Твой взгляд на мир: {worldview} Тебя интересует: {interests.lower()}. Тревожит: {fears.lower()}. {behavior}", "interests": interests + ".", "fears": fears + ".", "hostile": key in HOSTILE, "variants": variants})
    if len(rows) != 82 or len({row["id"] for row in rows}) != 82:
        raise ValueError("Approved brief must contain 82 distinct types")
    previous = read_json(ASSETS / "species.json", {})
    old = {row["id"]: row for row in previous.get("species", [])}
    for row in rows:
        for slot, variant in enumerate(row["variants"]):
            if row["id"] in old:
                variant["voiceId"] = old[row["id"]]["variants"][slot].get("voiceId", "")
    document = {"schemaVersion": 1, "minecraftVersion": "1.21.1", "source": "docs/mobtalk-0.2-plan.md", "species": rows}
    write_json(ASSETS / "species.json", document)
    return document


def archetype_motivation(label):
    stem = label.lower()
    choices = [
        (("забот", "общин", "защит", "своим", "верный"), "Сначала замечай, кому нужна защита или помощь; ценишь последовательные реальные поступки, а не лесть."),
        (("тревож", "робк", "осторож", "перестрах", "недовер"), "Проверяй риск и путь отступления, говори с конкретной оговоркой; доверие делает тебя спокойнее, но не слепо послушным."),
        (("исслед", "любопыт", "следопыт", "развед", "знаток", "коллекц"), "Ищи один интересный факт или закономерность в настоящем контексте, задавай точный вопрос и не выдумывай находки."),
        (("философ", "созерц", "мечта", "памят", "патриарх"), "Связывай текущий вопрос с одним понятным наблюдением, выдерживай спокойную паузу и возвращайся к практическому смыслу."),
        (("торгов", "продав", "выгод", "делец", "расчёт", "планиров", "снабжен"), "Сравни пользу, цену и последствия; предлагай конкретный обмен или решение, отказывайся от пустых обещаний."),
        (("караул", "страж", "дозор", "судья", "ревнит", "исполн", "хранител", "поряд", "педант", "перфек"), "Цени ясное правило, точную границу и ответственность; формулируй требование прямо, а исключение объясняй делом."),
        (("шут", "насмеш", "зубоскал", "циник", "ирони", "парод", "сплет", "рассказ"), "Реагируй короткой уместной шуткой или историей на происходящее, не унижай без повода и не повторяй одну шутку каждый ход."),
        (("забия", "агресс", "мстител", "таран", "громил", "буян", "мучител", "захват", "преслед", "ярост", "отрав", "палач"), "Проверяй чужую решимость, раздражайся сопротивлению и выражай намерение конкретно; ласковый тон не стирает настоящую враждебность."),
        (("власт", "надмен", "эстет", "модниц", "аристок", "горд", "тщеслав", "чемпион", "самоувер"), "Держись уверенно, оценивай вкус или выдержку собеседника; признавай достойный поступок, но не выпрашивай восхищение."),
        (("ворчун", "угрюм", "устав", "мрач", "отшель", "затвор", "одиноч", "молчун", "стоик", "невозмут"), "Цени покой и конкретность, говори скупо; раздражение выражай предметно, не превращай каждый ответ в одинаковую жалобу."),
        (("азарт", "акробат", "приключ", "бегун", "путешеств", "преодол", "провод", "лоцман", "практик", "приятел", "оптим"), "Ищи выполнимый следующий шаг и возможность движения; предложи один понятный вариант, не обещай недоступное действие."),
    ]
    return next((sentence for terms, sentence in choices if any(term in stem for term in terms)), "Отвечай исходя из своей конкретной привычки, замечай текущую просьбу и реальные последствия, избегай обязательной самопрезентации.")


def voice_style(target):
    if "quick" in target or "energetic" in target:
        return "Речь живая и порывистая, короткие ясные фразы; не тараторь непонятно."
    if "slow" in target or "measured" in target:
        return "Речь неспешная, весомые слова и короткие осмысленные паузы; сохраняй краткость."
    if "rough" in target or "raspy" in target:
        return "Речь шероховатая и прямолинейная, с резкими акцентами; слова остаются разборчивыми."
    if "precise" in target or "controlled" in target:
        return "Речь сухая и точная, ритм ровный, каждое уточнение по делу."
    if "theatrical" in target or "expressive" in target:
        return "Речь выразительная, интонация подчёркивает один смысл, не разыгрывай длинный монолог."
    return "Речь мягкая и связная, естественный разговорный ритм и спокойные пояснения."


def read_json(path, fallback):
    return json.loads(path.read_text(encoding="utf-8-sig")) if path.exists() else fallback


def write_json(path, value):
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(value, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")


def metadata(raw, provenance):
    voice_id = clean(raw.get("voice_id", raw.get("id")))
    languages = [item for item in raw.get("verified_languages", raw.get("verifiedLanguages", [])) if item.get("language") == "ru"]
    native = clean(raw.get("language")) == "ru"
    if not voice_id or not (native or languages):
        return None
    preview = next((item.get("preview_url") for item in languages if item.get("preview_url")), raw.get("preview_url", raw.get("previewUrl", "")))
    description = clean(raw.get("description"))
    rate = float(raw.get("rate") or 1)
    if not preview or not description or rate > 1:
        return None
    moderated = bool(raw.get("live_moderation_enabled", raw.get("liveModerationEnabled", False)))
    original_description = description
    if moderated:
        description += " [Библиотека: включена Live Moderation, возможна дополнительная задержка.]"
    return {"id": voice_id, "name": clean(raw.get("name")), "description": description, "previewUrl": preview,
            "language": "ru", "nativeLanguage": clean(raw.get("language")), "gender": clean(raw.get("gender")),
            "age": clean(raw.get("age")).replace("middle-aged", "middle_aged"), "descriptive": clean(raw.get("descriptive")), "useCase": clean(raw.get("use_case")),
            "verifiedLanguages": [{"language": "ru", "modelId": item.get("model_id", item.get("modelId", "")), "accent": item.get("accent", ""), "locale": item.get("locale", ""), "previewUrl": item.get("preview_url", item.get("previewUrl", ""))} for item in languages],
            "metadataStatus": "public_library_metadata_only", "previewStatus": "url_from_library_not_auditioned",
            "generationStatus": "not_tested", "targetModel": TARGET_MODEL, "source": provenance,
            "fetchedAt": datetime.now(timezone.utc).isoformat(timespec="seconds"), "freeUsersAllowed": raw.get("free_users_allowed"),
            "rate": rate, "liveModerationEnabled": moderated, "originalDescription": original_description,
            "targetModelVerifiedByLibrary": any(item.get("model_id", item.get("modelId")) == "eleven_flash_v2_5" for item in languages)}


def fetch_public(query):
    params = {"language": "ru", "page_size": 3, "page": 0, "include_custom_rates": "false", "include_live_moderated": "false", **query}
    url = SOURCE + "?" + urllib.parse.urlencode(params)
    request = urllib.request.Request(url, headers={"Accept":"application/json", "User-Agent":"MobTalk-PublicVoiceCatalog/1.0"})
    with urllib.request.urlopen(request, timeout=20) as response:
        return json.load(response), url


def score(voice, variant, hostile=True):
    words = set(variant["voiceRequirements"].split())
    description = " ".join(str(voice.get(key, "")) for key in ("name", "description", "descriptive", "useCase")).lower()
    synonyms = {
        "deep": ("deep", "bass", "baritone", "низк", "бас", "баритон", "глубок"),
        "low": ("low", "deep", "bass", "низк", "бас", "баритон"),
        "warm": ("warm", "velvet", "тёпл", "тепл", "бархат", "добр"),
        "soft": ("soft", "gentle", "мягк", "нежн", "ласк"),
        "bright": ("bright", "high", "light", "звонк", "высок", "ярк", "светл"),
        "light": ("light", "airy", "лёгк", "легк", "воздуш"),
        "rough": ("rough", "raspy", "husky", "хрип", "груб", "шерох"),
        "raspy": ("raspy", "husky", "gravel", "хрип", "сипл"),
        "calm": ("calm", "steady", "спокой", "размер", "нетороп"),
        "measured": ("measured", "slow", "steady", "размер", "медлен", "нетороп"),
        "quick": ("quick", "fast", "energetic", "быстр", "энерг", "порыв"),
        "energetic": ("energetic", "upbeat", "быстр", "энерг", "бодр", "живой"),
        "stern": ("stern", "serious", "authoritative", "строг", "суров", "серьёз", "серьез", "власт"),
        "authoritative": ("authoritative", "powerful", "власт", "авторитет", "мощн", "уверен"),
        "mysterious": ("mysterious", "dark", "haunting", "загад", "таинств", "мрачн"),
        "theatrical": ("theatrical", "dramatic", "character", "актёр", "актер", "театрал", "драмат"),
        "playful": ("playful", "funny", "comic", "игрив", "смешн", "озорн", "юмор"),
        "clear": ("clear", "precise", "articulate", "чётк", "четк", "ясн", "разбор"),
        "expressive": ("expressive", "эмоцион", "выраз", "ярк"),
    }
    value = sum(3 for word in words if any(term in description for term in synonyms.get(word, (word,))))
    value += 5 if voice.get("gender") == variant.get("preferredGender") else 0
    value += 3 if voice.get("age") == variant.get("preferredAge") else 0
    value += 4 if voice.get("nativeLanguage") == "ru" else 0
    value += 2 if voice.get("useCase") in {"characters_animation", "conversational", "narrative_story"} else 0
    value += 2 if voice.get("targetModelVerifiedByLibrary") else 0
    if words & {"deep", "low", "stern", "authoritative"}:
        if any(term in description for term in ("high-pitched", "mid–high", "childlike", "kids'", "cheerful", "sobbing", "bubbly")):
            value -= 18
    if words & {"soft", "warm", "gentle", "calm"}:
        if any(term in description for term in ("villain", "malevolent", "cruel", "evil", "brutal screams", "angry", "terrifying")):
            value -= 18
    if words & {"bright", "energetic", "playful", "quick"}:
        if any(term in description for term in ("sad,", "grief", "sobbing", "melanchol", "terror", "terrifying")):
            value -= 15
    if not hostile and any(term in description for term in ("villain", "malevolent", "cruel", "evil", "brutal", "angry", "terrifying", "demon", "horror", "rage")):
        value -= 24
    return value


def assign(document, voices):
    if len(voices) < 328:
        raise ValueError(f"Need 246 distinct assigned voices and 82 species reserves; only {len(voices)} real candidates available")
    used = set()
    for voice in voices.values():
        for key in ("assignedSpecies", "assignedArchetype", "reservedSpecies"):
            voice.pop(key, None)
    tasks = [(species, variant) for species in document["species"] for variant in species["variants"]]
    for species, variant in tasks:
        names = MANUAL_CAST.get(species["id"].split(":", 1)[1])
        if not names:
            continue
        name = names[species["variants"].index(variant)]
        matches = [voice for voice in voices.values() if clean(voice["name"]) == clean(name)]
        if len(matches) != 1 or matches[0]["id"] in used:
            raise ValueError(f"Hand cast must resolve to one observed, unused public ID: {name}")
        chosen = matches[0]
        variant["voiceId"] = chosen["id"]
        variant["castingEvidence"] = {"method": "hand_cast_from_public_description", "score": score(chosen, variant, species["hostile"]), "auditioned": False}
        chosen["assignedSpecies"] = species["id"]
        chosen["assignedArchetype"] = variant["name"]
        used.add(chosen["id"])
    tasks = [(species, variant) for species, variant in tasks if species["id"].split(":", 1)[1] not in MANUAL_CAST]
    # Cast serious antagonists before broad, flexible conversational parts.
    tasks.sort(key=lambda task: (not task[0]["hostile"], "deep" not in task[1]["voiceRequirements"], "raspy" not in task[1]["voiceRequirements"], task[0]["id"]))
    for species, variant in tasks:
        choices = [voice for voice in voices.values() if voice["id"] not in used and not voice.get("liveModerationEnabled")]
        if not choices:
            choices = [voice for voice in voices.values() if voice["id"] not in used]
        chosen = max(choices, key=lambda voice: (score(voice, variant, species["hostile"]), voice["id"]))
        variant["voiceId"] = chosen["id"]
        variant["castingEvidence"] = {"method": "public_description_and_labels", "score": score(chosen, variant, species["hostile"]), "auditioned": False}
        chosen["assignedSpecies"] = species["id"]
        chosen["assignedArchetype"] = variant["name"]
        used.add(chosen["id"])
    remaining = [voice_id for voice_id in voices if voice_id not in used]
    species_reserves = {}
    for species in sorted(document["species"], key=lambda species: (species["id"].split(":", 1)[1] not in MANUAL_CAST, not species["hostile"], species["id"])):
        chosen_id = max(remaining, key=lambda voice_id: (max(score(voices[voice_id], variant, species["hostile"]) for variant in species["variants"]) - (3 if voices[voice_id].get("liveModerationEnabled") else 0), voice_id))
        species_reserves[species["id"]] = chosen_id
        remaining.remove(chosen_id)
        voices[chosen_id]["reservedSpecies"] = species["id"]
    return [voice_id for voice_id in voices if voice_id not in used], species_reserves


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--fetch", action="store_true", help="Read public metadata only; stop on any authentication gate")
    parser.add_argument("--source", type=Path, help="Import an authorized read-only public voice-library metadata export")
    parser.add_argument("--assign", action="store_true", help="Assign 246 unique candidates and 82 distinct species reserves; requires 328 records")
    args = parser.parse_args()
    species = build_species()
    previous = read_json(ASSETS / "voices.json", {})
    voices = {voice["id"]: voice for voice in previous.get("voices", [])}
    if args.source:
        imported = read_json(args.source, {})
        rows = imported.get("voices", imported.get("data", {}).get("voices", [])) if isinstance(imported, dict) else imported
        for raw in rows:
            voice = metadata(raw, SOURCE + " (authorized read-only export)")
            if voice:
                voices[voice["id"]] = voice
    fetch_error = ""
    if args.fetch:
        queries = [{}] + [{"search": word} for word in ("deep", "warm", "raspy", "bright", "mysterious", "calm", "stern", "playful", "whisper", "energetic")]
        for query in queries:
            try:
                page, url = fetch_public(query)
                for raw in page.get("voices", []):
                    voice = metadata(raw, url)
                    if voice:
                        voices[voice["id"]] = voice
            except urllib.error.HTTPError as error:
                if error.code in {401, 403}:
                    fetch_error = f"Anonymous public search unavailable: HTTP {error.code}; no authentication bypass attempted."
                    break
                raise
    old_reserves = previous.get("reserveIds", [])
    reserve_ids = [voice_id for voice_id in old_reserves if voice_id in voices]
    assignment_error = ""
    species_reserves = previous.get("speciesReserves", {})
    if args.assign:
        try:
            reserve_ids, species_reserves = assign(species, voices)
            write_json(ASSETS / "species.json", species)
        except ValueError as error:
            assignment_error = str(error)
    assigned = {variant["voiceId"] for row in species["species"] for variant in row["variants"] if variant["voiceId"]}
    if not assigned:
        reserve_ids = list(voices)
    voice_doc = {"schemaVersion": 1, "targetModel": TARGET_MODEL, "generationStatus": "not_tested",
                 "catalogComplete": len(assigned) == 246, "assignedCount": len(assigned), "candidateCount": len(voices),
                 "collectionNote": fetch_error or ("Authorized read-only public-library export imported; no paid synthesis performed." if args.source else previous.get("collectionNote", "Public library metadata, without paid synthesis validation.")),
                 "voices": list(voices.values()), "reserveIds": reserve_ids, "speciesReserves": species_reserves}
    write_json(ASSETS / "voices.json", voice_doc)
    print(json.dumps({"species": len(species["species"]), "archetypes": 246, "realCandidates": len(voices),
                      "assigned": len(assigned), "reserves": len(reserve_ids), "generationTested": 0,
                      "collectionLimitation": fetch_error, "assignmentLimitation": assignment_error}, ensure_ascii=False))
    if assignment_error:
        raise SystemExit(2)


if __name__ == "__main__":
    main()
